// Robust IPC invoker with automatic fallback to window.electron.ipcRenderer
const invokeIpc = async (methodName, channel, ...args) => {
  if (typeof window !== 'undefined') {
    if (window.api && typeof window.api[methodName] === 'function') {
      return window.api[methodName](...args)
    }
    if (window.electron && window.electron.ipcRenderer && typeof window.electron.ipcRenderer.invoke === 'function') {
      return window.electron.ipcRenderer.invoke(channel, ...args)
    }
  }
  throw new Error(`API method "${methodName}" (channel: "${channel}") is not available. Please restart the dashboard application to apply updates.`)
}

const ProfileTelemetry = ({ profile, family, clearCounter }) => {
  const [historyData, setHistoryData] = useState(null);
  const [showHistoryModal, setShowHistoryModal] = useState(false);

  const handleClearHistory = async () => {
    if (!confirm('Are you sure you want to delete all connection logs for this profile?')) return;
    try {
      const res = await window.api.clearProfileHistory({ id: profile, family });
      if (res.success) {
        setHistoryData({
          currentIp: 'Unknown',
          currentTimezone: 'Unknown',
          previousIp: 'Unknown',
          previousTimezone: 'Unknown',
          history: []
        });
      } else {
        alert('Failed to clear history: ' + res.error);
      }
    } catch (e) {
      console.error(e);
    }
  };

  useEffect(() => {
    let active = true;
    window.api.getProfileHistory({ id: profile, family })
      .then(data => {
        if (active) setHistoryData(data);
      })
      .catch(console.error);
    return () => { active = false; };
  }, [profile, family, clearCounter]);

  if (!historyData) {
    return <div style={{ fontSize: '0.75rem', opacity: 0.5, marginTop: '0.5rem' }}>Loading network stats...</div>;
  }

  const { currentIp, currentTimezone, previousIp, previousTimezone, history } = historyData;

  return (
    <div style={{ marginTop: '0.75rem', padding: '0.75rem', background: 'rgba(255,255,255,0.03)', borderRadius: '8px', border: '1px solid rgba(255,255,255,0.05)' }}>
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.5rem', marginBottom: '0.5rem' }}>
        <div>
          <div style={{ fontSize: '0.7rem', opacity: 0.5, textTransform: 'uppercase', letterSpacing: '0.05em' }}>Current Network</div>
          <div style={{ fontSize: '0.8rem', fontWeight: 600, color: 'var(--accent-primary)', textOverflow: 'ellipsis', overflow: 'hidden', whiteSpace: 'nowrap' }} title={currentIp}>
            🌐 {currentIp}
          </div>
          <div style={{ fontSize: '0.7rem', opacity: 0.8, textOverflow: 'ellipsis', overflow: 'hidden', whiteSpace: 'nowrap' }} title={currentTimezone}>
            🕒 {currentTimezone}
          </div>
        </div>
        <div>
          <div style={{ fontSize: '0.7rem', opacity: 0.5, textTransform: 'uppercase', letterSpacing: '0.05em' }}>Previous Network</div>
          <div style={{ fontSize: '0.8rem', opacity: 0.8, textOverflow: 'ellipsis', overflow: 'hidden', whiteSpace: 'nowrap' }} title={previousIp}>
            🔄 {previousIp}
          </div>
          <div style={{ fontSize: '0.7rem', opacity: 0.6, textOverflow: 'ellipsis', overflow: 'hidden', whiteSpace: 'nowrap' }} title={previousTimezone}>
            🕒 {previousTimezone}
          </div>
        </div>
      </div>

      <div style={{ display: 'flex', gap: '0.5rem' }}>
        <button
          type="button"
          className="btn btn-secondary"
          style={{ 
            flex: 3, 
            padding: '0.25rem', 
            fontSize: '0.75rem', 
            background: 'rgba(255,255,255,0.02)',
            border: '1px solid rgba(255,255,255,0.05)',
            borderRadius: '4px',
            color: 'var(--text-secondary)'
          }}
          onClick={() => setShowHistoryModal(true)}
        >
          📜 View Logs ({history?.length || 0})
        </button>
        <button
          type="button"
          className="btn btn-secondary"
          style={{ 
            flex: 2, 
            padding: '0.25rem', 
            fontSize: '0.75rem', 
            borderColor: 'rgba(248, 113, 113, 0.3)',
            color: '#f87171',
            borderRadius: '4px',
            background: 'transparent'
          }}
          onClick={handleClearHistory}
          title="Clear Connection Logs for this profile"
        >
          Clear Logs
        </button>
      </div>

      {showHistoryModal && (
        <div style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: 'rgba(0,0,0,0.85)',
          backdropFilter: 'blur(8px)',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          zIndex: 99999,
          padding: '2rem'
        }}>
          <div style={{
            background: 'linear-gradient(135deg, #1e1e2e 0%, #11111b 100%)',
            border: '1px solid rgba(255,255,255,0.1)',
            borderRadius: '16px',
            width: '100%',
            maxWidth: '500px',
            padding: '1.5rem',
            boxShadow: '0 20px 40px rgba(0,0,0,0.5)',
            maxHeight: '80vh',
            display: 'flex',
            flexDirection: 'column'
          }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem', borderBottom: '1px solid rgba(255,255,255,0.1)', paddingBottom: '0.5rem' }}>
              <h3 style={{ margin: 0, display: 'flex', alignItems: 'center', gap: '0.5rem', color: '#ffffff' }}>
                📜 {profile} Telemetry Logs
              </h3>
              <button 
                className="btn btn-secondary" 
                style={{ padding: '0.2rem 0.5rem', border: 'none', background: 'transparent', color: '#ffffff', fontSize: '1.2rem', cursor: 'pointer' }} 
                onClick={() => setShowHistoryModal(false)}
              >
                ✕
              </button>
            </div>
            
            <div style={{ overflowY: 'auto', flex: 1, paddingRight: '0.5rem' }}>
              {history?.length === 0 ? (
                <div style={{ textAlign: 'center', padding: '2rem', opacity: 0.4, color: '#ffffff' }}>
                  No historical connections logged yet. Launch the bot to create a record.
                </div>
              ) : (
                <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                  {history.map((h, i) => (
                    <div key={i} style={{ 
                      padding: '0.75rem', 
                      background: i === 0 ? 'rgba(16, 185, 129, 0.05)' : 'rgba(255,255,255,0.02)', 
                      border: i === 0 ? '1px solid rgba(16, 185, 129, 0.2)' : '1px solid rgba(255,255,255,0.05)', 
                      borderRadius: '8px',
                      color: '#ffffff'
                    }}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.75rem', opacity: 0.5, marginBottom: '0.25rem' }}>
                        <span>#{history.length - i} connection</span>
                        <span>{new Date(h.timestamp).toLocaleString()}</span>
                      </div>
                      <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.85rem', fontWeight: 600 }}>
                        <span style={{ color: 'var(--accent-primary)' }}>IP: {h.ip}</span>
                        <span>TZ: {h.timezone}</span>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
            
            <div style={{ display: 'flex', gap: '1rem', marginTop: '1.5rem' }}>
              <button 
                type="button"
                className="btn btn-secondary" 
                style={{ flex: 1, borderColor: '#f87171', color: '#f87171', background: 'transparent' }} 
                onClick={handleClearHistory}
              >
                Clear History Logs
              </button>
              <button 
                type="button"
                className="btn btn-primary" 
                style={{ flex: 1 }} 
                onClick={() => setShowHistoryModal(false)}
              >
                Close History Log
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const highlightCode = (rawCode) => {
  return rawCode
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/(const|let|async|await|function|return|typeof|if|else|for|new)/g, '<span style="color:#c678dd;font-weight:bold">$1</span>')
    .replace(/(console\.log|switchFolder|readEmail|explorePage|scrollAndClick|page\.\w+|browser\.\w+)/g, '<span style="color:#61afef">$1</span>')
    .replace(/(`[^`]*`|\'[^']*\'|\"[^"]*\")/g, '<span style="color:#98c379">$1</span>')
    .replace(/(\/{2}.*)/g, '<span style="color:#5c6370;font-style:italic">$1</span>');
};

