  const getRecommendedConcurrency = () => {
    if (!stats || !stats.system || !stats.system.totalMem) return 2;
    const ramGb = stats.system.totalMem / (1024 * 1024 * 1024);
    const cores = stats.system.cpuCores || 4;
    const ramRecommended = Math.floor(ramGb / 1.5);
    return Math.max(1, Math.min(cores, ramRecommended));
  }

