  const getProfilesInScope = () => {
    if (schedulerSettings.scope === 'all') {
      return families.flatMap(f => (f.profiles || []).map(p => ({ family: f.name, name: p, id: `${f.name}/${p}` })));
    } else if (schedulerSettings.scope === 'family') {
      const f = families.find(fam => fam.name === schedulerSettings.targetFamily);
      return (f?.profiles || []).map(p => ({ family: f.name, name: p, id: `${f.name}/${p}` }));
    } else if (schedulerSettings.scope === 'profile') {
      if (!schedulerSettings.targetProfile) return [];
      const [fName, pName] = schedulerSettings.targetProfile.split('/');
      return [{ family: fName, name: pName, id: schedulerSettings.targetProfile }];
    }
    return [];
  };

  const handleStartWarmerForScope = async () => {
    const scopeProfiles = getProfilesInScope();
    if (scopeProfiles.length === 0) return alert('No profiles found in active scope! Please ensure you have selected a target profile or family on Card 1.');
    if (!confirm(`Are you sure you want to initialize progressive 90-day warm-up roadmaps for all ${scopeProfiles.length} profiles in the current scope?`)) return;

    // Generate mathematical 90-day progress warmth
    const warmupTasks = [];
    for (let day = 1; day <= 90; day++) {
      let watchMin = 5 + Math.floor((day / 90) * 40);
      let scrollChance = 10 + Math.floor((day / 90) * 80);
      let adClick = day > 30 ? (day > 60 ? '5% (Peak)' : '2% (Standard)') : '0% (Disabled)';
      let likeComment = day > 15 ? (day > 60 ? '20%' : '10%') : '0%';
      warmupTasks.push({
        day,
        watchMin,
        scrollChance,
        adClick,
        likeComment,
        active: true
      });
    }

    const updatedProfiles = { ...(schedulerSettings.profiles || {}) };
    scopeProfiles.forEach(p => {
      updatedProfiles[p.id] = {
        enabled: true,
        mode: 'warmer',
        warmerStartDate: new Date().toISOString(),
        warmerProgressDay: 1,
        warmerTasks: warmupTasks,
        tasks: []
      };
    });

    const updated = {
      ...schedulerSettings,
      profiles: updatedProfiles
    };
    await handleSaveSchedulerSettings(updated);
    alert(`🎉 90-Day Warming Roadmaps successfully initialized for all ${scopeProfiles.length} profiles!`);
  };

  const handleGenerateAiScheduleForScope = async () => {
    const scopeProfiles = getProfilesInScope();
    if (scopeProfiles.length === 0) return alert('No profiles found in active scope! Please ensure you have selected a target profile or family on Card 1.');
    if (!confirm(`AI will compile customized seasonal lifetime calendars for all ${scopeProfiles.length} profiles. This may take a moment. Proceed?`)) return;

    const provider = config.ai?.provider || 'deepseek';
    let apiKey = '';
    if (provider === 'deepseek') apiKey = config.ai?.deepseekApiKey;
    else if (provider === 'openai') apiKey = config.ai?.openaiApiKey;
    else if (provider === 'anthropic') apiKey = config.ai?.anthropicApiKey;
    else if (provider === 'gemini') apiKey = config.ai?.geminiApiKey;

    if (!apiKey) {
      alert(`Please set your API Key for ${(provider || '').toUpperCase()} in Settings first.`);
      return;
    }

    setIsScheduleGenerating(true);
    setSchedulerCompileProgress(`Starting AI generator loop for ${scopeProfiles.length} profiles...`);

    try {
      const updatedProfiles = { ...(schedulerSettings.profiles || {}) };

      for (let i = 0; i < scopeProfiles.length; i++) {
        const p = scopeProfiles[i];
        setSchedulerCompileProgress(`Compiling AI calendar ${i + 1} of ${scopeProfiles.length} (${p.family} - ${p.name})...`);

        const personality = personalities[p.id] || {};
        let timezone = 'UTC';
        const profileObj = proxies.find(pr => pr.assignedProfiles?.includes(p.id));
        if (profileObj?.timezone) {
          timezone = profileObj.timezone;
        } else {
          timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;
        }

        try {
          const res = await window.api.askAiSchedule({
            personality,
            device: 'random',
            browser: 'random',
            timezone,
            season: schedulerSeason,
            targetMonthlyAdClicks: schedulerSettings.targetMonthlyAdClicks || 10,
            provider: provider,
            apiKey: apiKey,
            profileId: p.name || p.id.split('/')[1] || p.id,
            family: p.family
          });

          if (res && res.tasks && Array.isArray(res.tasks)) {
            updatedProfiles[p.id] = {
              enabled: true,
              mode: 'lifetime',
              detectedSeason: res.detectedSeason || schedulerSeason || 'Auto-detected',
              tasks: res.tasks,
              warmerTasks: []
            };
          } else {
            console.warn(`AI compilation failed for ${p.id}. Using default placeholders.`);
            updatedProfiles[p.id] = {
              enabled: true,
              mode: 'lifetime',
              detectedSeason: schedulerSeason,
              tasks: [
                { time: '09:00', task: 'Search & Watch Video', desc: 'Auto fallback browser warm task', active: true },
                { time: '14:30', task: 'Like & Comment Engagement', desc: 'Auto fallback browser engagement', active: true }
              ],
              warmerTasks: []
            };
          }
        } catch (err) {
          console.error(`Error in generator for ${p.id}:`, err);
        }
      }

      const updated = {
        ...schedulerSettings,
        profiles: updatedProfiles
      };
      await handleSaveSchedulerSettings(updated);
      alert(`🎉 DeepSeek AI Lifetime Calendars compiled and initialized for all ${scopeProfiles.length} profiles!`);
    } catch (err) {
      alert('Error during generator loop: ' + err.message);
    } finally {
      setIsScheduleGenerating(false);
      setSchedulerCompileProgress('');
    }
  };

