  const convertProfileTimeToHostTime = (timeStr, targetTimezone) => {
    try {
      if (!timeStr) return '';
      const [hours, minutes] = timeStr.split(':').map(Number);

      const now = new Date();
      const tzFormatter = new Intl.DateTimeFormat('en-US', {
        timeZone: targetTimezone,
        year: 'numeric',
        month: 'numeric',
        day: 'numeric',
        hour: 'numeric',
        minute: 'numeric',
        second: 'numeric',
        hour12: false
      });

      const formattedParts = tzFormatter.formatToParts(now);
      const parts = {};
      formattedParts.forEach(p => { parts[p.type] = p.value; });

      const targetYear = Number(parts.year);
      const targetMonth = Number(parts.month) - 1;
      const targetDay = Number(parts.day);

      const targetLocalString = `${parts.year}-${String(parts.month).padStart(2, '0')}-${String(parts.day).padStart(2, '0')}T${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:00`;

      const utcString = now.toLocaleString('en-US', { timeZone: 'UTC' });
      const tzString = now.toLocaleString('en-US', { timeZone: targetTimezone });

      const utcDate = new Date(utcString);
      const tzDate = new Date(tzString);
      const offsetMs = tzDate.getTime() - utcDate.getTime();

      const targetUtcDate = new Date(Date.UTC(targetYear, targetMonth, targetDay, hours, minutes, 0));
      const taskUtcTimestamp = targetUtcDate.getTime() - offsetMs;

      const hostLocalDate = new Date(taskUtcTimestamp);
      return hostLocalDate.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    } catch (err) {
      console.warn('Timezone conversion error:', err);
      return '';
    }
  };

