  const handleAskDbAi = async () => {
    if (!selectedDb || !botSettings.outputDir) return
    if (!dbQueryText.trim()) {
      alert('Please enter a question first.')
      return
    }
    const provider = config.ai?.provider || 'deepseek'
    let apiKey = ''
    if (provider === 'deepseek') apiKey = config.ai?.deepseekApiKey
    else if (provider === 'openai') apiKey = config.ai?.openaiApiKey
    else if (provider === 'anthropic') apiKey = config.ai?.anthropicApiKey
    else if (provider === 'gemini') apiKey = config.ai?.geminiApiKey

    if (!apiKey) {
      alert(`Please set your API Key for ${(provider || '').toUpperCase()} in Settings first.`)
      return
    }

    setIsDbAiLoading(true)
    setDbAiError('')
    setDbAiResult(null)

    try {
      const dbPath = botSettings.outputDir + '\\' + selectedDb

      // 1. Fetch schema
      const schemaRes = await window.api.queryDb(dbPath, "SELECT sql FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'", [])
      if (!schemaRes.success) {
        throw new Error('Failed to retrieve database schema: ' + schemaRes.error)
      }

      const schemaText = schemaRes.data.map(row => row.sql).filter(Boolean).join('\n\n')

      // 2. Ask AI to generate SQL
      const sqlRes = await window.api.askDbAiSql({
        question: dbQueryText,
        schema: schemaText,
        provider: provider,
        apiKey: apiKey
      })

      if (!sqlRes.success) {
        throw new Error(sqlRes.error || 'Failed to generate SQL query.')
      }

      const generatedSql = sqlRes.sql

      // 3. Execute query
      const queryRes = await window.api.queryDb(dbPath, generatedSql, [])
      if (!queryRes.success) {
        throw new Error('Failed to run generated SQL query: ' + queryRes.error)
      }

      const rawResult = queryRes.data

      // 4. Explain query result
      const explainRes = await window.api.askDbAiExplain({
        question: dbQueryText,
        sql: generatedSql,
        result: rawResult,
        provider: provider,
        apiKey: apiKey
      })

      if (!explainRes.success) {
        throw new Error(explainRes.error || 'Failed to generate explanation.')
      }

      setDbAiResult({
        sql: generatedSql,
        raw: rawResult,
        answer: explainRes.answer
      })

    } catch (e) {
      setDbAiError(e.message)
    } finally {
      setIsDbAiLoading(false)
    }
  }

