    if (editingProfile && editingProfile.name && editingProfile.name !== editingProfile.id) {
      const res = await window.api.renameProfile(editingProfile.id, editingProfile.name, editingProfile.family)
      if (res.success) {
        window.api.getFamilies().then(setFamilies)
        setEditingProfile(null)
      } else {
        alert('Error renaming profile: ' + res.error)
      }
    } else {
      setEditingProfile(null)
    }
