      if (dataCopy.settings.customWebsiteInteractionMin === '') dataCopy.settings.customWebsiteInteractionMin = config.automation?.customWebsiteInteractionMin ?? 30;
      if (dataCopy.settings.customWebsiteInteractionMax === '') dataCopy.settings.customWebsiteInteractionMax = config.automation?.customWebsiteInteractionMax ?? 60;
      if (dataCopy.settings.customWebsiteAdClickChance === '') dataCopy.settings.customWebsiteAdClickChance = config.automation?.customWebsiteAdClickChance ?? 30;
      if (dataCopy.settings.customWebsiteAdInteractMin === '') dataCopy.settings.customWebsiteAdInteractMin = config.automation?.customWebsiteAdInteractMin ?? 45;
      if (dataCopy.settings.customWebsiteAdInteractMax === '') dataCopy.settings.customWebsiteAdInteractMax = config.automation?.customWebsiteAdInteractMax ?? 90;
