  const handleCheckAiBalance = async () => {
    const provider = config.ai?.provider || 'deepseek'
    let apiKey = ''
    if (provider === 'deepseek') apiKey = config.ai?.deepseekApiKey
    else if (provider === 'openai') apiKey = config.ai?.openaiApiKey
    else if (provider === 'anthropic') apiKey = config.ai?.anthropicApiKey
    else if (provider === 'gemini') apiKey = config.ai?.geminiApiKey

    setAiBalance(null)

    if (provider !== 'deepseek') {
      let consoleUrl = ''
      if (provider === 'openai') consoleUrl = 'https://platform.openai.com/settings/organization/billing/overview'
      else if (provider === 'anthropic') consoleUrl = 'https://console.anthropic.com/settings/billing'
      else if (provider === 'gemini') consoleUrl = 'https://aistudio.google.com/'

      setAiBalance({
        success: false,
        warning: true,
        message: `${(provider || '').toUpperCase()} does not provide a public API endpoint to check credit balances with standard API keys.`,
        link: consoleUrl
      })
      return
    }

    if (!apiKey) {
      setAiBalance({
        success: false,
        error: 'API Key is missing. Please enter your DeepSeek API Key and save settings first.'
      })
      return
    }

    setIsCheckingBalance(true)
    try {
      const res = await window.api.checkAiBalance({ provider, apiKey })
      if (res && res.success) {
        setAiBalance({
          success: true,
          balance: res.balance
        })
      } else {
        setAiBalance({
          success: false,
          error: res?.error || 'Failed to fetch balance details.'
        })
      }
    } catch (e) {
      setAiBalance({
        success: false,
        error: e.message
      })
    } finally {
      setIsCheckingBalance(false)
    }
  }

