      if (configCopy.automation.maxWatchMinutes === '') configCopy.automation.maxWatchMinutes = 5;
      if (configCopy.automation.minAdInteractionSeconds === '') configCopy.automation.minAdInteractionSeconds = 10;
      if (configCopy.automation.maxAdInteractionSeconds === '') configCopy.automation.maxAdInteractionSeconds = 30;
      
