      if (configCopy.automation.customWebsiteInteractionMax === '') configCopy.automation.customWebsiteInteractionMax = 60;
      if (configCopy.automation.customWebsiteAdClickChance === '') configCopy.automation.customWebsiteAdClickChance = 30;
      if (configCopy.automation.customWebsiteAdInteractMin === '') configCopy.automation.customWebsiteAdInteractMin = 45;
      if (configCopy.automation.customWebsiteAdInteractMax === '') configCopy.automation.customWebsiteAdInteractMax = 90;
