  const handleTestSignalServer = async () => {
    setIsTestingSignalServer(true)
    setSignalServerTestResult(null)
    const targetUrl = (signalsServerUrlInput || 'http://localhost:4000').replace(/\/+$/, '')
    const apiKey = signalsApiKeyInput || 'vfl_live_key_2026'
    const startTime = Date.now()

    try {
      if (window.api && window.api.testSignalServer) {
        try {
          const res = await window.api.testSignalServer({
            serverUrl: targetUrl,
            apiKey: apiKey
          })
          if (res) {
            setSignalServerTestResult(res)
            return
          }
        } catch (ipcErr) {
          console.warn('IPC testSignalServer fallback to direct fetch:', ipcErr.message)
        }
      }

      // Direct HTTP fetch fallback from frontend
      const healthRes = await fetch(`${targetUrl}/api/health`, {
        method: 'GET',
        headers: { 'x-api-key': apiKey },
        signal: AbortSignal.timeout(6000)
      })
      const latencyMs = Date.now() - startTime
      if (healthRes.ok) {
        let serverData = {}
        try { serverData = await healthRes.json() } catch (e) {}
        setSignalServerTestResult({ success: true, latencyMs, serverData })
      } else {
        setSignalServerTestResult({ success: false, latencyMs, error: `HTTP ${healthRes.status}: ${healthRes.statusText}` })
      }
    } catch (e) {
      const latencyMs = Date.now() - startTime
      let userMsg = e.message
      if (e.name === 'TimeoutError' || e.message.includes('timeout') || e.message.includes('Failed to fetch')) {
        userMsg = `Connection timed out to ${targetUrl}. Port 4000 is likely blocked by the VPS OS firewall (iptables/ufw) or Node is listening on 127.0.0.1 instead of 0.0.0.0.`
      }
      setSignalServerTestResult({ success: false, latencyMs, error: userMsg })
    } finally {
      setIsTestingSignalServer(false)
    }
  }

