                                      height: '20px',
                                      borderRadius: '5px',
                                      cursor: 'pointer',
                                      background: isFamilyAllSelected
                                        ? 'linear-gradient(135deg, #10b981 0%, #059669 100%)'
                                        : isFamilyPartiallySelected
                                          ? 'rgba(16, 185, 129, 0.25)'
                                          : 'rgba(255, 255, 255, 0.05)',
                                      border: isFamilyAllSelected
                                        ? '1.5px solid #34d399'
                                        : isFamilyPartiallySelected
                                          ? '1.5px solid #10b981'
                                          : '1.5px solid rgba(255, 255, 255, 0.2)',
