                    const seasonName = livePredictionsData.seasonName || '';
                    
                    const isBundesliga = seasonName.toLowerCase().includes('bundesliga');
                    const maxRounds = isBundesliga ? 30 : 38;
                    const matchesPerRound = isBundesliga ? 8 : 10;
                    const totalMatches = maxRounds * matchesPerRound;

                    const roundNumbers = predictions.map(p => p.round_number).filter(r => r !== null && r !== undefined);
                    const minRound = roundNumbers.length > 0 ? Math.min(...roundNumbers) : 1;
                    const matchesPlayedBefore = (minRound - 1) * matchesPerRound;
                    
                    const scoredCount = predictions.filter(p => p.scored_status === 1).length;
