                      const [h, a] = p.actual_score.split(':').map(Number);
                      const [htH, htA] = (p.actual_ht_score || "0:0").split(':').map(Number);
                      const totGoals = h + a;
                      const htGoals = htH + htA;
                      const shGoals = totGoals - htGoals;

                      const probs = p.predicted_probs || {};

                      let actualRes = 'Draw';
                      if (h > a) actualRes = 'Home';
                      else if (a > h) actualRes = 'Away';
                      stats.matchResult.total++;
                      if (p.predicted_result === actualRes) stats.matchResult.correct++;

                      stats.over15.total++;
                      if (totGoals > 1.5) stats.over15.correct++;
                      stats.under15.total++;
                      if (totGoals < 1.5) stats.under15.correct++;

                      stats.over25.total++;
                      if (totGoals > 2.5) stats.over25.correct++;
                      stats.under25.total++;
                      if (totGoals < 2.5) stats.under25.correct++;

                      stats.over35.total++;
                      if (totGoals > 3.5) stats.over35.correct++;
                      stats.under35.total++;
                      if (totGoals < 3.5) stats.under35.correct++;

                      stats.over45.total++;
                      if (totGoals > 4.5) stats.over45.correct++;
                      stats.under45.total++;
                      if (totGoals < 4.5) stats.under45.correct++;

