                      stats.odd.total++;
                      if (totGoals % 2 === 1) stats.odd.correct++;
                      stats.even.total++;
                      if (totGoals % 2 === 0) stats.even.correct++;

                      stats.ht1stHalf.total++;
                      if (htGoals > shGoals) stats.ht1stHalf.correct++;
                      stats.ht2ndHalf.total++;
                      if (shGoals > htGoals) stats.ht2ndHalf.correct++;
                      stats.htEqual.total++;
