                      display: 'flex', alignItems: 'center', gap: '0.45rem',
                      boxShadow: executorPlatform === 'sportybet' ? '0 0 12px rgba(229, 27, 36, 0.35)' : '0 0 12px rgba(37, 99, 235, 0.35)',
