                      border: '1px solid rgba(239, 68, 68, 0.5)',
                      color: theme === 'light' ? '#dc2626' : 'var(--danger)',
                      fontWeight: 700,
                      cursor: 'pointer',
                      display: 'flex', alignItems: 'center', gap: '0.4rem',
                      boxShadow: '0 0 12px rgba(239, 68, 68, 0.2)'
