                    border: '1px solid ' + (theme === 'light' ? 'rgba(6, 182, 212, 0.3)' : 'rgba(6, 182, 212, 0.4)'),
                    color: theme === 'light' ? '#0891b2' : '#22d3ee',
                    fontWeight: 600,
                    cursor: isFetchingTracker ? 'not-allowed' : 'pointer',
                    display: 'flex', alignItems: 'center', gap: '0.4rem'
